-- Funcional e CrossFit (feature 1, etapa 1): catálogo de 56 exercícios do
-- material "Funcional e CrossFit no FitOS". 40 entram novos (imagem servida de
-- public/media/exercises); os 16 que já existiam ganham só as categorias,
-- músculos secundários, nomes alternativos e a métrica — sem duplicar nem
-- trocar imagem. Idempotente: ON CONFLICT por origem e externalId; os UPDATE
-- só reescrevem os mesmos valores.

ALTER TABLE "exercises" ADD COLUMN     "aliases" TEXT[] DEFAULT ARRAY[]::TEXT[],
ADD COLUMN     "categories" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
ADD COLUMN     "metric" TEXT,
ADD COLUMN     "searchText" TEXT,
ADD COLUMN     "secondaryMuscles" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];

